mapper.select:
SELECT document_id, source_content_hash, ocr_signature, total_pages, created_at, updated_at
FROM document_ocr_checkpoints
WHERE document_id = #{documentId}

mapper.insert:
INSERT INTO document_ocr_checkpoints (
    document_id, source_content_hash, ocr_signature, total_pages, created_at, updated_at
) VALUES (
    #{documentId}, #{sourceContentHash}, #{ocrSignature}, #{totalPages}, #{createdAt}, #{updatedAt}
)
ON CONFLICT(document_id) DO UPDATE SET
    source_content_hash = excluded.source_content_hash,
    ocr_signature = excluded.ocr_signature,
    total_pages = excluded.total_pages,
    updated_at = excluded.updated_at

INSERT INTO document_ocr_checkpoint_pages (
    document_id, page_number, page_text, created_at, updated_at
) VALUES (
    #{documentId}, #{pageNumber}, #{pageText}, #{createdAt}, #{updatedAt}
)
ON CONFLICT(document_id, page_number) DO UPDATE SET
    page_text = excluded.page_text,
    updated_at = excluded.updated_at

mapper.select:
SELECT COUNT(*)
FROM document_ocr_checkpoints
WHERE document_id = #{documentId}
  AND source_content_hash = #{sourceContentHash}
